import { readFileSync } from 'node:fs';
const POS = ['path','qkey','qval','frag','fragqk','fragqv','user','pass'];
// what the injected text is surrounded by, so we can locate it
const rows = {};
for (const p of POS) {
  rows[p] = readFileSync(`/workspace/sweep_${p}.tsv`,'utf8').trim().split('\n').map(l=>{
    const [pos,hex,form,st,...rest] = l.split('\t');
    return {pos,hex,form,st,out:rest.join('\t')};
  });
}
// Classify: for each pos+hex, compare raw-form output vs pct-form output, and
// determine what appeared between the sentinels.
const sentinel = {
  path:   [/\/p(.*)q(?:$|[?#])/, 'p','q'],
};
function extract(pos, out) {
  // locate between markers
  let m;
  switch(pos){
    case 'path':   m = out.match(/^http:\/\/n\.com\/p([\s\S]*)q$/); break;
    case 'qkey':   m = out.match(/^http:\/\/n\.com\/p\?k([\s\S]*)k=v$/); break;
    case 'qval':   m = out.match(/^http:\/\/n\.com\/p\?k=v([\s\S]*)v$/); break;
    case 'frag':   m = out.match(/^http:\/\/n\.com\/p#f([\s\S]*)f$/); break;
    case 'fragqk': m = out.match(/^http:\/\/n\.com\/p#f\?k([\s\S]*)k=v$/); break;
    case 'fragqv': m = out.match(/^http:\/\/n\.com\/p#f\?k=v([\s\S]*)v$/); break;
    case 'user':   m = out.match(/^http:\/\/u([\s\S]*)u:pw@n\.com\/p$/); break;
    case 'pass':   m = out.match(/^http:\/\/un:p([\s\S]*)p@n\.com\/p$/); break;
  }
  return m ? m[1] : null;
}
const table = {};
for (const p of POS) {
  table[p] = {};
  for (const r of rows[p]) {
    const ex = r.st==='ERR' ? 'ERR' : extract(p, r.out);
    table[p][r.hex+':'+r.form] = ex===null ? 'STRUCT:'+r.out : ex;
  }
}
// Print compact report
const name = h => { const c=String.fromCharCode(parseInt(h,16)); return c===' '?'SP':c; };
for (const p of POS) {
  console.log('\n===== '+p+' =====');
  const lines=[];
  for (let i=32;i<=126;i++){
    const h=i.toString(16).toUpperCase().padStart(2,'0');
    const raw=table[p][h+':raw'], pct=table[p][h+':pct'];
    const ch=String.fromCharCode(i);
    const rawTag = raw===ch ? 'KEEP' : (raw==='%'+h ? 'PCT' : (raw&&raw.startsWith('STRUCT')? 'STRUCT' : (raw==='ERR'?'ERR':JSON.stringify(raw))));
    const pctTag = pct===ch ? 'DECODED' : (pct==='%'+h||pct==='%'+h.toLowerCase() ? 'KEPT%' : (pct&&pct.startsWith('STRUCT')?'STRUCT':(pct==='ERR'?'ERR':JSON.stringify(pct))));
    lines.push(`${h} ${JSON.stringify(ch).padEnd(6)} raw=${rawTag.padEnd(10)} pct=${pctTag}`);
  }
  console.log(lines.join('\n'));
}
EOF
